function migrateTranslationProgress(){
  if(state.translationRevision===TRANSLATION_REVISION)return false;
  const fromV3=state.translationRevision==='2026-11-02-voa-v3';
  const previous=Object.fromEntries(Object.entries(state.progress).filter(([id])=>/^t[rt]\d{4}$/.test(id)&&(!fromV3||TRANSLATION_CHANGED_FROM_V3.has(id.replace(/^tt/,'tr')))));
  if(Object.keys(previous).length){
    const archives=Array.isArray(state.translationArchives)?state.translationArchives:[];
    state.translationArchives=[...archives,{revision:state.translationRevision||'original-v1',archivedAt:new Date().toISOString(),progress:previous}];
    for(const id of Object.keys(previous))delete state.progress[id];
  }
  state.translationRevision=TRANSLATION_REVISION;
  return true;
}
