function learningPool(items){const now=Date.now(),ready=w=>!state.progress[w.id]||state.progress[w.id].due<=now;const chosen=TranslationCards.shuffle(items);chosen.sort((a,b)=>Number(!ready(a))-Number(!ready(b))||(state.progress[a.id]?.attempts||0)-(state.progress[b.id]?.attempts||0));return chosen}
function uniqueWords(items){const seen=new Set();return items.filter(w=>{const key=w.word.toLowerCase();if(seen.has(key))return false;seen.add(key);return true})}
function start(review){window.MobileUI?.cardMode(false);window.Pronunciation?.stop();stopPractice();TranslationAudio.stop();let items;if(review){items=due().sort((a,b)=>state.progress[a.id].due-state.progress[b.id].due).slice(0,state.goal)}else{const pools=[learningPool(everydayLearningItems()),learningPool(translationItems()),WordGap.pool(),learningPool(everydayLearningItems().map(typedItem)),learningPool(translationItems().map(typedItem))];items=[];const used=new Set();for(let round=0;items.length<state.goal&&round<state.goal;round++){for(const pool of pools){let w;while(pool.length){const candidate=pool.shift(),id=candidate.sourceId||candidate.id;if(!used.has(id)){w=candidate;used.add(id);break}}if(w)items.push(w);if(items.length>=state.goal)break}}}if(!items.length){toast('지금 복습할 항목이 없어요.');return}session={items,index:0,correct:0,answered:false,review};quiz()}
function startTranslation(items,mode='cards'){
 window.MobileUI?.cardMode(false);
 window.Pronunciation?.stop();stopPractice();TranslationAudio.stop();
 if(!items.length){toast('학습할 문장이 없어요.');return}
 if(!['cards','typing','mixed'].includes(mode))mode='cards';
 const candidates=mode==='typing'?items.map(typedItem):items;
 const pool=learningPool(candidates),seen=new Set();
 let selected=pool.filter(w=>{const id=w.sourceId||w.id;if(seen.has(id))return false;seen.add(id);return true}).slice(0,state.goal);
 if(mode==='mixed')selected=selected.map((w,i)=>i%2?typedItem(w):w);
 const everyday=selected.every(w=>w.collection==='everyday');
 session={items:selected,index:0,correct:0,answered:false,review:false,returnPage:everyday?'everyday':'home'};
 page=everyday?'everyday':'translation';document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));
 quiz();window.scrollTo(0,0)
}
