function stats(){const entries=Object.entries(state.history).sort((a,b)=>b[0].localeCompare(a[0]));const total=entries.reduce((n,[,v])=>n+v.total,0),correct=entries.reduce((n,[,v])=>n+v.correct,0);main.innerHTML=title('YOUR GROWTH','학습 기록','어제보다 조금 더 익숙해진 영어를 만나세요.')+`<div class="stats-grid">${[['총 학습 문장',total+''],['전체 정답률',total?Math.round(correct/total*100)+'%':'—'],['학습한 날짜',entries.length+'일'],['연속 학습',streak()+'일']].map(([l,v])=>`<section class="card"><p class="muted">${l}</p><div class="stat-num">${v}</div></section>`).join('')}</div><section class="card" style="margin-top:20px"><h2>날짜별 학습</h2>${entries.length?entries.slice(0,60).map(([d,v])=>`<div class="history-row"><span>${d}</span><span>${v.total}문장 · 정답 ${v.correct}개${(v.translationTotal||0)>(v.everydayTotal||0)?`<small class="translation-breakdown">VOA 카드 ${(v.translationTotal||0)-(v.everydayTotal||0)-(v.typingTotal||0)+(v.everydayTypingTotal||0)} · 직접 입력 ${(v.typingTotal||0)-(v.everydayTypingTotal||0)}</small>`:""}${v.everydayTotal?`<small class="translation-breakdown">생활영어 카드 ${v.everydayTotal-(v.everydayTypingTotal||0)} · 직접 입력 ${v.everydayTypingTotal||0}</small>`:""}</span></div>`).join(''):'<p class="muted">첫 학습을 시작하면 이곳에 기록이 쌓여요.</p>'}</section>`}
function settings(){main.innerHTML=title('MAKE IT YOURS','설정','학습 목표와 소중한 기록을 관리하세요.')+`<div class="settings"><section class="card"><h2>학습 설정</h2><label>하루 학습 목표<select id="goal">${[5,10,15,20].map(n=>`<option value="${n}" ${state.goal===n?'selected':''}>${n}문장</option>`).join('')}</select></label><label>정답 확인 후 자동 발음<input id="sound" type="checkbox" ${state.sound?'checked':''}></label></section><section class="card"><details><summary>홈 화면에 설치</summary><p class="muted">이 사이트 주소를 휴대폰 Safari에서 여세요. 정보카은 로그인 없이 사용할 수 있어요.</p><ol class="install-steps"><li><strong>iPhone · Safari</strong>에서 공유 버튼 → ‘홈 화면에 추가’</li><li><strong>Android · Chrome</strong>에서 메뉴 ⋮ → ‘홈 화면에 추가’ 또는 ‘앱 설치’</li></ol><p class="muted">설치 메뉴는 브라우저와 기기에 따라 달라요. 네이티브 앱이 아닌 설치형 웹앱입니다.</p><button class="secondary" id="install">설치하기</button></details></section><section class="card"><details><summary>오프라인 저장</summary><p class="muted" id="offlineStatus" role="status">저장 상태를 확인해 보세요.</p><button class="secondary" id="offlineCheck">오프라인 저장 확인</button><p class="muted">자료를 처음 저장하거나 업데이트할 때는 인터넷이 필요해요. ChatGPT 대화에는 인터넷과 ChatGPT 로그인이 필요합니다. iPhone이 사이트 데이터를 지우면 다시 연결해 자료를 받아야 해요.</p></details></section><section class="card"><h2>내 기록 백업</h2><p class="muted">기록은 이 기기의 브라우저에 저장됩니다. 다른 기기와 자동 동기화되지 않으며, 브라우저 데이터를 지우면 사라질 수 있어요.</p><div class="actions"><button class="secondary" id="export">백업 파일 내보내기 ↓</button><button class="secondary" id="import">백업 파일 가져오기 ↑</button><input type="file" id="importFile" accept="application/json,.json" hidden></div></section><section class="card"><details><summary>정보카 정보</summary><p class="settings-about">단어 ${fmt(contentCounts().dictionary)}개 · VOA 번역 3,000문장 · 생활영어 1,000문장 · 토익 문법 150개 · 패턴 200개. 정답은 간격을 두고, 오답은 바로 복습합니다. 카드 배열과 직접 입력의 복습 기록은 각각 저장됩니다. 듣기·녹음만 한 경우 정답률에는 포함하지 않습니다.</p><p class="settings-about">발음 점수는 기기 내 음성 인식으로 계산한 연습용 추정치이며, 강세·억양 또는 발음 정확도를 검증한 평가는 아닙니다. ChatGPT 대화는 별도 ChatGPT 화면에서 이용합니다.</p><p><a href="data-credits.html" target="_blank" rel="noopener" style="color:var(--accent)">자료 출처 및 라이선스 ↗</a></p></details></section><section class="card"><button class="text-btn danger" id="reset">모든 학습 기록 초기화</button></section></div>`;document.querySelector('#offlineCheck').onclick=showOfflineStatus;showOfflineStatus();document.querySelector('#goal').onchange=e=>{state.goal=Number(e.target.value);save();toast('학습 목표를 저장했어요.')};document.querySelector('#sound').onchange=e=>{state.sound=e.target.checked;save()};document.querySelector('#install').onclick=async()=>{if(installEvent){await installEvent.prompt();installEvent=null}else toast('Safari의 공유 또는 Chrome의 메뉴에서 홈 화면에 추가하세요.')};document.querySelector('#export').onclick=()=>{const b=new Blob([JSON.stringify({format:'wordgarden',version:1,data:state},null,2)],{type:'application/json'}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download=`wordgarden-${dayKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};document.querySelector('#import').onclick=()=>document.querySelector('#importFile').click();document.querySelector('#importFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>5000000)throw Error();const b=JSON.parse(await f.text()),d=b.data;if(b.format!=='wordgarden'||b.version!==1||!d||!Array.isArray(d.custom)||!d.progress||!d.history||![5,10,15,20].includes(d.goal)||typeof d.sound!=='boolean')throw Error();if(d.wordAnswerMode!==undefined&&!['typing','choice','mixed'].includes(d.wordAnswerMode))throw Error();for(const w of d.custom)if(typeof w.id!=='string'||!w.id.startsWith('c')||!['word','meaning','sentence','translation','category'].every(k=>typeof w[k]==='string')||!w.word.trim()||w.word.length>60)throw Error();for(const p of Object.values(d.progress))if(!p||!Number.isInteger(p.level)||p.level<0||p.level>7||![p.due,p.attempts,p.correct].every(Number.isFinite)||p.correct>p.attempts||p.correct<0)throw Error();for(const [k,v]of Object.entries(d.history))if(!/^\d{4}-\d{2}-\d{2}$/.test(k)||!v||![v.total,v.correct].every(Number.isInteger)||v.total<0||v.correct<0||v.correct>v.total)throw Error();for(const v of Object.values(d.history)){for(const k of ['translationTotal','translationCorrect','typingTotal','typingCorrect','everydayTotal','everydayCorrect','everydayTypingTotal','everydayTypingCorrect'])if(v[k]!==undefined&&(!Number.isInteger(v[k])||v[k]<0||v[k]>v.total))throw Error();if((v.translationCorrect||0)>(v.translationTotal||0)||(v.typingCorrect||0)>(v.typingTotal||0)||(v.typingTotal||0)>(v.translationTotal||0))throw Error();
 const et=v.everydayTotal||0,ec=v.everydayCorrect||0,ett=v.everydayTypingTotal||0,etc=v.everydayTypingCorrect||0;
 const tr=v.translationTotal||0,tc=v.translationCorrect||0,tt=v.typingTotal||0,ttc=v.typingCorrect||0;
 const parts=[[et-ett,ec-etc],[ett,etc],[tr-et-tt+ett,tc-ec-ttc+etc],[tt-ett,ttc-etc],[v.total-tr,v.correct-tc]];
 if(et>tr||ec>tc||ett>tt||etc>ttc||parts.some(([total,correct])=>total<0||correct<0||correct>total))throw Error();}if(confirm('현재 기록을 백업 파일의 기록으로 바꿀까요?')){state=d;migrateTranslationProgress();save();settings();toast('백업을 가져왔어요.')}}catch{toast('올바른 정보카 백업 파일을 선택해 주세요.')}};document.querySelector('#reset').onclick=()=>{if(confirm('학습 기록과 직접 추가한 단어를 모두 삭제할까요? 먼저 백업을 권장해요.')){state={progress:{},history:{},custom:[],goal:10,sound:true,translationRevision:TRANSLATION_REVISION};save();show('home')}}}
